var compose_ps_default = `
	uniform sampler2D ssaoTexture;
	float dSsao;
	vec3 applySsao(vec3 color, vec2 uv) {
		#ifdef SSAO_LIGHTING
			#if DEBUG_COMPOSE == ssao
				dSsao = texture2DLod(ssaoTexture, uv, 0.0).r;
			#endif
			return color;
		#else
			dSsao = texture2DLod(ssaoTexture, uv, 0.0).r;
			return color * dSsao;
		#endif
	}
	vec3 debugSsao() {
		return vec3(dSsao);
	}
`;
export {
	compose_ps_default as default
};
